import React, { useEffect, useState } from "react";
import { Link, useLocation } from "react-router-dom";

const SuccessPage = () => {
  const location = useLocation();
  const [order, setOrder] = useState(null);

  useEffect(() => {
    if (location.state) {
      setOrder(location.state);
    } else {
      const saved = localStorage.getItem("lastOrder");
      if (saved) setOrder(JSON.parse(saved));
    }
  }, [location.state]);

  if (!order) {
    return (
      <div className="p-6 text-center">
        <h1 className="text-2xl font-bold mb-4">No Order Found</h1>
        <Link to="/" className="text-blue-600 underline">
          Go back to Home
        </Link>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto p-6 bg-white rounded-lg shadow-lg mt-10">
      {/* 🎉 Success Header */}
      <div className="text-center mb-6">
        <h1 className="text-4xl font-bold text-green-600 mb-2">🎉 Order Placed Successfully!</h1>
        <p className="text-gray-600">
          Thank you for your purchase, {order.name || "Customer"}! We’ve received your order.
        </p>
      </div>

      {/* Order Summary Card */}
      <div className="border rounded-lg p-6 shadow-md bg-gray-50">
        <h2 className="text-2xl font-semibold text-purple-700 mb-4">Order Summary</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <p><strong>Name:</strong> {order.name}</p>
            <p><strong>Email:</strong> {order.email}</p>
            <p><strong>Phone:</strong> {order.phone}</p>
          </div>
          <div>
            <p><strong>Shipping Address:</strong> {order.shippingAddress}</p>
            <p><strong>Billing Address:</strong> {order.billingAddress}</p>
            <p><strong>Payment Method:</strong> {order.paymentMethod}</p>
          </div>
        </div>

        <p className="font-bold text-lg text-right mb-4">Total: Rs {order.total || order.totalAmount}</p>

        {/* Items */}
        {order.items?.length > 0 && (
          <div className="mt-4">
            <h3 className="font-semibold mb-2 text-gray-700">Items:</h3>
            <ul className="space-y-2">
              {order.items.map((item, idx) => (
                <li
                  key={idx}
                  className="flex justify-between p-2 border rounded bg-white"
                >
                  <span>Product ID {item.productId} × {item.quantity}</span>
                  <span>Rs {item.price * item.quantity}</span>
                </li>
              ))}
            </ul>
          </div>
        )}
      </div>

      {/* Back to Shop */}
      <div className="text-center mt-6">
        <Link
          to="/"
          className="inline-block bg-purple-600 text-white px-6 py-3 rounded-lg hover:bg-purple-700 transition"
        >
          Continue Shopping
        </Link>
      </div>
    </div>
  );
};

export default SuccessPage;
